/**
 * One consistent, human-sounding voice for the whole app (concept explainer and AI interviewer):
 * Gemini's "Kore" voice, generated by the backend (/tts) and cached.
 *
 * The browser's built-in voice is used only when the natural voice is unavailable
 * (no Gemini key, offline), never as a mid-session substitute, so the voice stays the same.
 * Playback speed (1x–2x) is shared everywhere and remembered.
 */
export type VoiceStyle = 'teacher' | 'interviewer';

export const SPEEDS = [1, 1.25, 1.5, 2] as const;

const audioCache = new Map<string, Promise<string | null>>();
let currentAudio: HTMLAudioElement | null = null;
let speakToken = 0;
let naturalAvailable: boolean | null = null;
let quotaReached = false;
const noticeListeners = new Set<(quota: boolean) => void>();

/** True once today's free natural-voice limit is used up (the backup browser voice is used after that). */
export function isQuotaReached() { return quotaReached; }
export function onVoiceNotice(fn: (quota: boolean) => void) {
  noticeListeners.add(fn);
  return () => { noticeListeners.delete(fn); };
}
function markQuotaReached() {
  quotaReached = true;
  naturalAvailable = false;
  noticeListeners.forEach(fn => fn(true));
}
let speed = 1;
const speedListeners = new Set<(s: number) => void>();

try {
  const saved = typeof window !== 'undefined' ? parseFloat(localStorage.getItem('gapx_voice_speed') || '1') : 1;
  if ((SPEEDS as readonly number[]).includes(saved)) speed = saved;
} catch (_) {}

export function getSpeed() { return speed; }

/** Changes the playback speed everywhere, including speech that is already playing. */
export function setSpeed(value: number) {
  speed = value;
  try { localStorage.setItem('gapx_voice_speed', String(value)); } catch (_) {}
  if (currentAudio) currentAudio.playbackRate = value;
  speedListeners.forEach(fn => fn(value));
}

export function onSpeedChange(fn: (s: number) => void) {
  speedListeners.add(fn);
  return () => { speedListeners.delete(fn); };
}

async function checkNatural(apiBase: string): Promise<boolean> {
  if (naturalAvailable !== null) return naturalAvailable;
  try {
    const r = await fetch(`${apiBase}/tts/status`);
    const d = r.ok ? await r.json() : {};
    naturalAvailable = Boolean(d.available) && !d.quota_exhausted;
    if (d.available && d.quota_exhausted) markQuotaReached();
  } catch (_) {
    naturalAvailable = false;
  }
  return naturalAvailable;
}

/** Fetches (and caches) natural-voice audio; resolves to an object URL or null if it failed. */
export function prefetchSpeech(apiBase: string, token: string | null, text: string, _style: VoiceStyle = 'teacher'): Promise<string | null> {
  const key = text;
  if (!audioCache.has(key)) {
    const p = (async () => {
      if (!token || !(await checkNatural(apiBase))) return null;
      for (let attempt = 0; attempt < 2; attempt++) {
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), 45000);
        try {
          const r = await fetch(`${apiBase}/tts`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
            body: JSON.stringify({ text, style: 'teacher' }),
            signal: controller.signal,
          });
          if (r.ok) return URL.createObjectURL(await r.blob());
          if (r.status === 429) { markQuotaReached(); return null; }
          if (r.status === 401) return null;
        } catch (_) {
          /* retry once */
        } finally {
          clearTimeout(timer);
        }
      }
      return null;
    })();
    audioCache.set(key, p);
    p.then(url => { if (!url) audioCache.delete(key); });
  }
  return audioCache.get(key)!;
}

/** Most human-sounding installed English voice (used only when the natural voice is unavailable). */
export function bestBrowserVoice(): SpeechSynthesisVoice | null {
  if (typeof window === 'undefined' || !('speechSynthesis' in window)) return null;
  const voices = window.speechSynthesis.getVoices().filter(v => v.lang.toLowerCase().startsWith('en'));
  if (!voices.length) return null;
  const score = (v: SpeechSynthesisVoice) => {
    const n = v.name.toLowerCase();
    let s = 0;
    if (n.includes('natural') || n.includes('neural') || n.includes('online')) s += 50;
    if (n.includes('google')) s += 30;
    if (n.includes('premium') || n.includes('enhanced')) s += 25;
    if (/aria|jenny|ava|emma|sonia|libby|neerja|samantha|serena/.test(n)) s += 12;  // warm female voices, closest to Kore
    if (/en-(us|gb|in)/i.test(v.lang)) s += 5;
    if (n.includes('desktop') || n.includes('zira') || n.includes('david')) s -= 10;
    return s;
  };
  return [...voices].sort((a, b) => score(b) - score(a))[0];
}

function splitSentences(text: string): string[] {
  return (text.match(/[^.!?]+[.!?]*/g) || [text]).map(s => s.trim()).filter(Boolean);
}

function browserSpeak(text: string, onStart?: () => void, onProgress?: (f: number) => void, startFraction = 0): Promise<void> {
  return new Promise(resolve => {
    if (typeof window === 'undefined' || !('speechSynthesis' in window)) { resolve(); return; }
    const synth = window.speechSynthesis;
    synth.cancel();
    const voice = bestBrowserVoice();
    const sentences = splitSentences(text);
    const words = sentences.map(x => x.split(/\s+/).length);
    const total = words.reduce((a, b) => a + b, 0) || 1;
    const before = (k: number) => words.slice(0, k).reduce((a, b) => a + b, 0) / total;
    const myToken = speakToken;
    let i = 0;
    while (i < sentences.length - 1 && before(i + 1) <= startFraction) i++;
    let first = true;
    const next = () => {
      if (myToken !== speakToken || i >= sentences.length) { resolve(); return; }
      onProgress?.(before(i));
      const u = new SpeechSynthesisUtterance(sentences[i++]);
      if (voice) u.voice = voice;
      u.rate = 0.96 * speed;
      if (first && onStart) u.onstart = () => onStart();
      first = false;
      u.onend = () => setTimeout(next, 180 / speed);
      u.onerror = () => resolve();
      synth.speak(u);
    };
    next();
  });
}

/** Stops any speech that's playing. */
export function stopSpeaking() {
  speakToken++;
  if (currentAudio) { currentAudio.pause(); currentAudio = null; }
  if (typeof window !== 'undefined' && 'speechSynthesis' in window) window.speechSynthesis.cancel();
}

type SpeakOpts = { onStart?: () => void; onProgress?: (fraction: number) => void; startFraction?: number };

async function playOne(apiBase: string, token: string | null, text: string, myToken: number, useNatural: boolean, opts: SpeakOpts): Promise<void> {
  if (useNatural) {
    const url = await prefetchSpeech(apiBase, token, text);
    if (myToken !== speakToken) return;
    if (url) {
      await new Promise<void>(resolve => {
        const audio = new Audio(url);
        audio.playbackRate = speed;           // browsers keep the natural pitch when speeding up
        (audio as any).preservesPitch = true;
        currentAudio = audio;
        audio.onplay = () => opts.onStart?.();
        audio.onloadedmetadata = () => {
          if (opts.startFraction && isFinite(audio.duration)) audio.currentTime = opts.startFraction * audio.duration;
        };
        audio.ontimeupdate = () => { if (audio.duration) opts.onProgress?.(audio.currentTime / audio.duration); };
        audio.onended = () => resolve();
        audio.onerror = () => resolve();
        audio.onpause = () => resolve();
        audio.play().catch(() => resolve());
      });
      return;
    }
  }
  if (myToken !== speakToken) return;
  await browserSpeak(text, opts.onStart, opts.onProgress, opts.startFraction || 0);
}

/** Speaks text in the app's single voice at the chosen speed. Resolves when finished or stopped. */
export async function speak(apiBase: string, token: string | null, text: string, _style: VoiceStyle = 'teacher',
  opts: SpeakOpts = {}): Promise<void> {
  stopSpeaking();
  const myToken = speakToken;
  const useNatural = Boolean(token) && await checkNatural(apiBase);
  if (myToken !== speakToken) return;
  await playOne(apiBase, token, text, myToken, useNatural, opts);
}

/**
 * Speaks several pieces back to back (e.g. a short reaction, then the next question).
 * All pieces are requested at once, so later ones are ready by the time earlier ones finish.
 */
export async function speakParts(apiBase: string, token: string | null, parts: string[], opts: { onStart?: () => void } = {}): Promise<void> {
  stopSpeaking();
  const myToken = speakToken;
  const pieces = parts.map(p => (p || '').trim()).filter(Boolean);
  const useNatural = Boolean(token) && await checkNatural(apiBase);
  if (myToken !== speakToken) return;
  if (useNatural) pieces.forEach(p => prefetchSpeech(apiBase, token, p));
  let started = false;
  for (const piece of pieces) {
    if (myToken !== speakToken) return;
    await playOne(apiBase, token, piece, myToken, useNatural, {
      onStart: () => { if (!started) { started = true; opts.onStart?.(); } },
    });
  }
}
